static inline double sign(double x)
{
    double f_c_scale = 0.2;
    double vel_threshold = IdleVelocityThreshold;
    if (x > vel_threshold)
        return f_c_scale;
    else if (x < -vel_threshold)
        return -f_c_scale;
    else
        return 0.0;
}

